ass=\"hljs-attribute\">z-index</span>: <span class=\"hljs-number\">999</span>; <span class=\"hljs-comment\">/* Встановлюємо z-index, щоб модальне вікно було поверх інших елементів */</span>\n}\n\n<span class=\"hljs-selector-class\">.modal-content</span> {\n  <span class=\"hljs-attribute\">background-color</span>: <span class=\"hljs-number\">#fefefe</span>; <span class=\"hljs-comment\">/* Колір фону вікна */</span>\n  <span class=\"hljs-attribute\">margin</span>: auto; <span class=\"hljs-comment\">/* Вирівнюємо вікно по центру екрана */</span>\n  <span class=\"hljs-attribute\">padding</span>: <span class=\"hljs-number\">20px</span>; <span class=\"hljs-comment\">/* Відступи від країв вікна */</span>\n  <span class=\"hljs-attribute\">border</span>: <span class=\"hljs-number\">1px</span> solid <span class=\"hljs-number\">#888</span>; <span class=\"hljs-comment\">/* Рамка вікна */</span>\n  <span class=\"hljs-attribute\">width</span>: <span class=\"hljs-number\">80%</span>; <span class=\"hljs-comment\">/* Ширина вікна */</span>\n  <span class=\"hljs-attribute\">max-width</span>: <span class=\"hljs-number\">600px</span>; <span class=\"hljs-comment\">/* Максимальна ширина вікна */</span>\n  <span class=\"hljs-attribute\">position</span>: relative; <span class=\"hljs-comment\">/* Відносна позиція */</span>\n  <span class=\"hljs-attribute\">top</span>: <span class=\"hljs-number\">50%</span>; <span class=\"hljs-comment\">/* Розташування вікна в центрі екрана */</span>\n  <span class=\"hljs-attribute\">transform</span>: <span class=\"hljs-built_in\">translateY</span>(-<span class=\"hljs-number\">50%</span>); <span class=\"hljs-comment\">/* Вирівнюємо вікно по вертикалі */</span>\n}\n\n<span class=\"hljs-comment\">/* Стилі для хрестика закриття вікна */</span>\n<span class=\"hljs-selector-class\">.close</span> {\n  <span class=\"hljs-attribute\">position</span>: absolute; <span class=\"hljs-comment\">/* Абсолютна позиція */</span>\n  <span class=\"hljs-attribute\">top</span>: <